composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      DB_SERVER_HOST: "{{serviceName}}-mysql"
      DB_SERVER_PORT: 3306
      MYSQL_DATABASE: zabbix
      MYSQL_USER: zabbix
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      ZBX_SERVER_HOST: {{env.ZBX_SERVER_HOST}}
      PHP_TZ: {{env.PHP_TZ}}
    depends_on:
      - {{serviceName}}-mysql
  {{serviceName}}-mysql:
    image: mysql:8.0
    container_name: {{serviceName}}-mysql
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: zabbix
      MYSQL_USER: zabbix
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_PASSWORD}}
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
